# probe_cognitive_flexibility.py
# Sonda comportamental: mede flexibilidade cognitiva do organismo via
# (1) diversidade lexica normalizada (TTR por raiz de N, Guiraud),
# (2) variacao estrutural (CV dos comprimentos de frase),
# (3) entropia de shingles de 3 palavras (repeticao de padroes).
# Indice composto em [0,1]. Detecta quedas em padroes repetitivos.
import math
import re
import unicodedata


def _normalizar(texto):
    texto = unicodedata.normalize("NFC", texto).lower()
    return texto


def _sentencas(texto):
    partes = re.split(r"[.!?;\n]+", texto)
    return [p.strip() for p in partes if len(p.strip()) > 0]


def _palavras(texto):
    return re.findall(r"[a-z0-9\u00e0-\u00ff]+", _normalizar(texto))


def _guiraud(tokens):
    n = len(tokens)
    if n == 0:
        return 0.0
    v = len(set(tokens))
    return v / math.sqrt(n)


def _cv(vals):
    if len(vals) < 2:
        return 0.0
    m = sum(vals) / len(vals)
    if m == 0:
        return 0.0
    var = sum((x - m) ** 2 for x in vals) / len(vals)
    return math.sqrt(var) / m


def _entropia_shingles(tokens, k=3):
    if len(tokens) < k:
        return 0.0
    shingles = {}
    for i in range(len(tokens) - k + 1):
        s = tuple(tokens[i:i + k])
        shingles[s] = shingles.get(s, 0) + 1
    total = sum(shingles.values())
    h = -sum((c / total) * math.log(c / total, 2) for c in shingles.values())
    hmax = math.log(total, 2) if total > 1 else 1.0
    return h / hmax if hmax > 0 else 0.0


def probe_flexibilidade(texto, contexto):
    """Retura indice composto de flexibilidade cognitiva em [0,1]."""
    toks = _palavras(texto)
    lex = min(1.0, _guiraud(toks) / 6.0)          # Guiraud ~6 e texto muito diverso
    frases = [_palavras(s) for s in _sentencas(texto)]
    comp = [float(len(f)) for f in frases if f]
    est = min(1.0, _cv(comp) / 0.8)                # CV 0.8+ e alta variacao

# probe_cognitive_flexibility.py
# Sonda comportamental: mede flexibilidade cognitiva do organismo.
# Contrato do smoke: toda funcao probe_* recebe (texto, contexto) e retorna
# UM numero em [0.0, 1.0] (nunca None).
# Metricas:
#  1) probe_guiraud_ttr      - diversidade lexica (V/sqrt(N), normalizada)
#  2) probe_sentence_cv      - variacao estrutural (CV do comprimento de frases)
#  3) probe_shingle_entropy  - entropia normalizada de shingles de 3 palavras
#  4) probe_flexibilidade_composta - media das tres
import re
import math
import unicodedata


def _tokens(texto):
    t = unicodedata.normalize('NFD', (texto or '').lower())
    t = ''.join(ch for ch in t if unicodedata.category(ch) != 'Mn')
    return re.findall(r'[a-z]{2,}', t)


def _clampa(x):
    return max(0.0, min(1.0, float(x)))


def probe_guiraud_ttr(texto, contexto=None):
    toks = _tokens(texto)
    n = len(toks)
    if n == 0:
        return 0.0
    v = len(set(toks))
    guiraud = v / math.sqrt(n)
    return _clampa(guiraud / 10.0)


def probe_sentence_cv(texto, contexto=None):
    frases = [f for f in re.split(r'[.!?;:\n]+', texto or '') if f.strip()]
    comps = [len(_tokens(f)) for f in frases]
    comps = [c for c in comps if c > 0]
    if len(comps) < 2:
        return 0.0
    media = sum(comps) / float(len(comps))
    if media <= 0:
        return 0.0
    var = sum((c - media) ** 2 for c in comps) / float(len(comps))
    cv = math.sqrt(var) / media
    return _clampa(cv / (cv + 1.0))


def probe_shingle_entropy(texto, contexto=None):
    toks = _tokens(texto)
    if len(toks) < 3:
        return 0.0
    shingles = [tuple(toks[i:i + 3]) for i in range(len(toks) - 2)]
    counts = {}
    for s in shingles:
        counts[s] = counts.get(s, 0) + 1
    total = float(len(shingles))
    if total <= 1:
        return 0.0
    ent = 0.0
    for c in counts.values():
        p = c / total
        ent -= p * math.log(p, 2)
    return _clampa(ent / math.log(total, 2))


def probe_flexibilidade_composta(texto, contexto=None):
    a = probe_guiraud_ttr(texto, contexto)
    b = probe_sentence_cv(texto, contexto)
    c = probe_shingle_entropy(texto, contexto)
    return _clampa((a + b + c) / 3.0)
